-- Reviewed against requireTenantIntegrationManager in whatsapp-connection.functions.ts. Meta settings already require platform admin or tenant owner/admin; direct Data API writes must enforce the same rule. Keep existing read policy and service_role access. No connection rows or credentials change.
drop policy whatsapp_connections_insert_member on public.whatsapp_connections;
create policy whatsapp_connections_insert_member on public.whatsapp_connections for insert to authenticated with check (owner_user_id=auth.uid() and exists (select 1 from public.tenant_members tm where tm.tenant_id=whatsapp_connections.tenant_id and tm.user_id=auth.uid() and (lower(tm.member_role) in ('owner','admin','administrator') or exists (select 1 from public.user_roles ur where ur.user_id=auth.uid() and ur.role='admin'))));
drop policy whatsapp_connections_update_member on public.whatsapp_connections;
create policy whatsapp_connections_update_member on public.whatsapp_connections for update to authenticated using (exists (select 1 from public.tenant_members tm where tm.tenant_id=whatsapp_connections.tenant_id and tm.user_id=auth.uid() and (lower(tm.member_role) in ('owner','admin','administrator') or exists (select 1 from public.user_roles ur where ur.user_id=auth.uid() and ur.role='admin')))) with check (owner_user_id=auth.uid() and exists (select 1 from public.tenant_members tm where tm.tenant_id=whatsapp_connections.tenant_id and tm.user_id=auth.uid() and (lower(tm.member_role) in ('owner','admin','administrator') or exists (select 1 from public.user_roles ur where ur.user_id=auth.uid() and ur.role='admin'))));
